#include "../src/game/stage_intro.hpp"
#include "../src/game/flying_scenery.hpp"
#include <cassert>
#include "../src/game/flying_events.hpp"
int main(int argc,char**argv){assert(argc==2);shin::AssetStore a(argv[1]);for(auto*n:shin::flying_intro_assets)a.image(n);shin::StageIntro intro(2);int voices=0;bool done=false;for(unsigned t=0;t<30000&&!done;t+=16){auto f=intro.update(t,false);voices+=int(f.sounds.size());done=f.action==shin::CutsceneFrame::resume_level;}assert(done&&voices==2&&intro.phase()==16);shin::StageIntro skip(2);assert(skip.update(0,true).action==shin::CutsceneFrame::resume_level);shin::FlyingScenery clouds;shin::IndexedSurface f(853,480);std::vector<shin::game::MapPlacement> m(1);m[0].type=0x3a;m[0].cell_x=10;m[0].cell_y=5;clouds.tick(m,0,0,a,f);assert(clouds.active_count()==1);for(int i=0;i<100;++i)clouds.tick(m,0,0,a,f);assert(clouds.active_count()==0);clouds.tick(m,0,0,a,f);assert(clouds.active_count()==0);shin::FlyingEvents ev;shin::PlayerPayload player;shin::initialize_player_payload(player,10,5);assert(ev.start(77,100));assert(!ev.stops_scroll());player.at(0xfc)=3;int startx=player.at(8);for(unsigned t=100;t<6900;t+=16)ev.tick(player,t,false,player.at(8)-320,0,a,f,[](unsigned){});assert(player.at(0xfc)==0&&player.at(8)>startx);ev.tick(player,7000,false,0,0,a,f,[](unsigned){});assert(!ev.active()&&player.at(0x54)==0);assert(ev.start(76,7100)&&ev.stops_scroll());shin::FlyingScenery edge;std::vector<shin::game::MapPlacement> boundary(1);boundary[0].type=0x3a;boundary[0].cell_x=21;boundary[0].cell_y=5;f.origin_x=106;edge.tick(boundary,0,0,a,f);assert(edge.active_count()==0);edge.tick(boundary,32,0,a,f);assert(edge.active_count()==1);for(unsigned stage=0;stage<3;++stage){shin::StageIntro guarded(stage,true);assert(guarded.update(0,true).action!=shin::CutsceneFrame::resume_level);assert(guarded.update(16,true).action!=shin::CutsceneFrame::resume_level);guarded.update(32,false);assert(guarded.update(48,true).action==shin::CutsceneFrame::resume_level);}shin::StageIntro fourth(3);bool finished4=false;int voice4=0;for(unsigned t=0;t<5000&&!finished4;t+=16){auto q=fourth.update(t,false);for(auto&d:q.draws)a.image(d.resource);voice4+=int(q.sounds.size());finished4=q.action==shin::CutsceneFrame::resume_level;}assert(finished4&&voice4==1);for(unsigned stage=4;stage<=6;++stage){shin::StageIntro later(stage);bool done=false;for(unsigned t=0;t<180000&&!done;t+=16){auto out=later.update(t,false);for(auto&d:out.draws)a.image(d.resource);done=out.action==shin::CutsceneFrame::resume_level;}assert(done);}}
